
(function(){const { $, $$, read, write, uid, esc, money, date, today, notify }=window.OP;const KEY='np_crm_pymes_v1';let state=read(KEY,{contacts:[],opportunities:[]});const stages=['Prospecto','Calificado','Propuesta','Ganado','Perdido'];
function persist(){write(KEY,state);render()}
function render(){const open=state.opportunities.filter(o=>!['Ganado','Perdido'].includes(o.stage));const weighted=open.reduce((s,o)=>s+Number(o.value||0)*Number(o.probability||0)/100,0);const overdue=open.filter(o=>o.nextDate&&o.nextDate<today()).length; $('[data-kpi="contacts"]').textContent=state.contacts.length; $('[data-kpi="open"]').textContent=open.length; $('[data-kpi="pipeline"]').textContent=money(weighted); $('[data-kpi="overdue"]').textContent=overdue;const contactSelect=$('#oppContact');const old=contactSelect.value;contactSelect.innerHTML='<option value="">Sin asignar</option>'+state.contacts.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');contactSelect.value=old;const term=($('#crmSearch').value||'').toLowerCase();$('#pipelineBoard').innerHTML=stages.map(stage=>{const items=state.opportunities.filter(o=>o.stage===stage&&(`${o.name} ${o.contactName}`.toLowerCase().includes(term)));return `<div class="op-lane"><h4>${stage}<span>${items.length}</span></h4>${items.length?items.map(o=>`<article class="op-item"><strong>${esc(o.name)}</strong><small>${esc(o.contactName||'Sin contacto')} · ${money(o.value)}</small><small>${o.nextDate?`Próximo: ${date(o.nextDate)}`:'Sin próxima acción'}</small><select data-stage="${esc(o.id)}">${stages.map(s=>`<option ${s===o.stage?'selected':''}>${s}</option>`).join('')}</select></article>`).join(''):'<p class="op-muted">Sin oportunidades</p>'}</div>`}).join('');$('#contactsTable').innerHTML=state.contacts.length?`<div class="op-table-wrap"><table class="op-table"><thead><tr><th>Contacto</th><th>Persona</th><th>Teléfono</th><th>Correo</th><th>Oportunidades</th><th></th></tr></thead><tbody>${state.contacts.map(c=>`<tr><td><strong>${esc(c.name)}</strong><br><small>${esc(c.notes||'')}</small></td><td>${esc(c.person)}</td><td>${esc(c.phone)}</td><td>${esc(c.email)}</td><td>${state.opportunities.filter(o=>o.contactId===c.id).length}</td><td><button class="op-button danger" data-delete-contact="${esc(c.id)}">Eliminar</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="op-empty">Aún no hay contactos.</div>'}
$('#contactForm').addEventListener('submit',e=>{e.preventDefault();const c={id:uid(),name:$('#contactName').value.trim(),person:$('#contactPerson').value.trim(),phone:$('#contactPhone').value.trim(),email:$('#contactEmail').value.trim(),notes:$('#contactNotes').value.trim(),createdAt:new Date().toISOString()};if(!c.name)return;state.contacts.unshift(c);e.target.reset();persist();notify('Contacto guardado.','good')});$('#opportunityForm').addEventListener('submit',e=>{e.preventDefault();const contact=state.contacts.find(c=>c.id===$('#oppContact').value);const o={id:uid(),name:$('#oppName').value.trim(),contactId:contact?.id||'',contactName:contact?.name||'',value:Number($('#oppValue').value||0),stage:$('#oppStage').value,probability:Number($('#oppProbability').value||0),nextDate:$('#oppNextDate').value,nextAction:$('#oppNextAction').value.trim(),createdAt:new Date().toISOString()};if(!o.name)return;state.opportunities.unshift(o);e.target.reset();$('#oppProbability').value=25;persist();notify('Oportunidad agregada.','good')});$('#crmSearch').addEventListener('input',render);document.addEventListener('change',e=>{if(e.target.matches('[data-stage]')){const o=state.opportunities.find(x=>x.id===e.target.dataset.stage);if(o){o.stage=e.target.value;if(o.stage==='Ganado')o.probability=100;if(o.stage==='Perdido')o.probability=0;persist();notify('Etapa actualizada.','good')}}});document.addEventListener('click',e=>{const id=e.target.dataset.deleteContact;if(id){if(confirm('¿Eliminar este contacto?')){state.contacts=state.contacts.filter(c=>c.id!==id);state.opportunities=state.opportunities.map(o=>o.contactId===id?{...o,contactId:'',contactName:''}:o);persist()}}});$('#clearCrm').addEventListener('click',()=>{if(confirm('¿Eliminar todos los contactos y oportunidades?')){state={contacts:[],opportunities:[]};persist();notify('CRM vacío.')}});render()})();